import sys

def slow(data):
    sums = {}
    get = sums.get
    for line in data.split(b'\n')[1:]:
        if not line:
            continue
        parts = line.split(b',')
        if len(parts) < 3:
            continue
        cat = parts[1].strip()
        v = parts[2].strip()
        neg = v.startswith(b'-')
        if neg:
            v = v[1:]
        if b'.' in v:
            a, b = v.split(b'.', 1)
            b = (b + b'00')[:2]
            c = (int(a) if a else 0) * 100 + int(b)
        else:
            c = int(v) * 100 if v else 0
        if neg:
            c = -c
        sums[cat] = get(cat, 0) + c
    return {k: v for k, v in sums.items()}, True

def fast(data):
    # header "id,cat,val\n" then rows "id,cat,val\n"; flat split on commas
    t = data.split(b',')
    n = len(t)
    if n < 3 or (n - 2) % 2:
        return None
    cats = t[3::2]
    vals = t[4::2]
    if len(cats) != len(vals):
        return None
    sums = {}
    get = sums.get
    for c, v in zip(cats, vals):
        i = v.find(b'\n')
        if i >= 0:
            v = v[:i]
        if v.endswith(b'\n'):
            v = v[:-1]
        sums[c] = get(c, 0.0) + float(v)
    return sums

def main():
    data = sys.stdin.buffer.read()
    sums = None
    if not (b'"' in data or b'\r' in data or b' ' in data):
        f = fast(data)
        if f is not None:
            # convert float sums to exact cents
            sums = {k: int(round(v * 100)) for k, v in f.items()}
    if sums is None:
        s, _ = slow(data)
        sums = s
    out = []
    for cat in sorted(sums):
        c = sums[cat]
        sign = '-' if c < 0 else ''
        c = abs(c)
        out.append('%s%s,%d.%02d' % (sign, cat.decode(), c // 100, c % 100))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))

main()

